"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[3237],{23237:e=>{e.exports=JSON.parse('{"meta":{"title":"Skill Alexa Muslim Companion : l\u2019Athan sur votre Echo - iMuslim Life","description":"Muslim Companion diffuse l\u2019Athan sur votre Amazon Echo \xe0 vos heures de pri\xe8re, avec le Coran, les adhkar, le Hifz Coach et le mode Ramadan. Gratuit. Configuration sur alexa.imuslimlife.com."},"hero":{"title":"Muslim Companion pour Alexa","lede":"L\u2019Athan \xe0 vos heures de pri\xe8re locales, les adhkar apr\xe8s la pri\xe8re, la r\xe9citation du Coran et les rappels de votre mosqu\xe9e, sur votre Amazon Echo.","live":"\u2714 Disponible sur Alexa","dashboard":"Ouvrir le tableau de bord","tryWeb":"Essayer l\u2019app web","imgAlt":"Appareil Amazon Alexa","athan":"\xab Allahu Akbar... \xbb","maghrib":"Maghrib \xe0 19 h 45"},"how":{"h2":"Comment \xe7a marche","sub":"Installez votre muezzin personnel en trois \xe9tapes simples, en moins de cinq minutes.","s1":{"h3":"Activez le skill","p":"Ouvrez l\u2019app Alexa sur votre t\xe9l\xe9phone, cherchez <b>Muslim Companion</b> et touchez <i>Enable to Use</i>. Dites ensuite en anglais \xab <q>{{p1}}</q> \xbb (Alexa, ouvre Muslim Companion) pour confirmer."},"s2":{"h3":"Connectez-vous et configurez","p":"Rendez-vous sur <a>alexa.imuslimlife.com</a>, connectez-vous, confirmez votre position, choisissez la voix de l\u2019Athan et suivez votre mosqu\xe9e (par exemple AMCC) pour les rappels d\u2019iqama et de Joumou\u2019a.","voice":"<b>Ou \xe0 la voix :</b> \xab <q>{{p1}}</q> \xbb (r\xe8gle la m\xe9thode de calcul sur ISNA) et \xab <q>{{p2}}</q> \xbb (r\xe8gle le madhab sur hanafite), sans tableau de bord. Voir les commandes vocales ci-dessous."},"s3":{"h3":"Cr\xe9ez une routine et profitez","p":"Dans l\u2019app Alexa, cr\xe9ez une routine : quand le capteur <i>Muslim Companion Azan</i> s\u2019ouvre, ouvrir <i>Muslim Companion</i>. Votre Echo diffuse alors l\u2019Athan automatiquement \xe0 chaque pri\xe8re. Notre <a>guide d\u2019installation pas \xe0 pas</a> vous accompagne avec des captures d\u2019\xe9cran."}},"features":{"h2":"Fonctionnalit\xe9s cl\xe9s","sub":"Tout se configure sur alexa.imuslimlife.com, et chaque option reste d\xe9sactiv\xe9e tant que vous ne l\u2019activez pas","soon":"Bient\xf4t : relecture par un savant","items":{"athan":{"title":"L\u2019Athan \xe0 vos heures de pri\xe8re","description":"Votre Echo diffuse l\u2019Athan \xe0 vos heures locales pour les cinq pri\xe8res, avec un choix de voix et un Athan sp\xe9cial pour Fajr."},"masjid":{"title":"Masjid Connect","description":"Suivez votre mosqu\xe9e (comme AMCC) et recevez un rappel avant chaque iqama et avant la Joumou\u2019a, aux horaires publi\xe9s par la mosqu\xe9e."},"quran":{"title":"R\xe9citation du Coran","description":"Plus de 30 r\xe9citateurs renomm\xe9s. Une sourate apr\xe8s l\u2019Athan, ou le Coran tout au long de la journ\xe9e, en reprenant l\xe0 o\xf9 vous vous \xeates arr\xeat\xe9."},"adhkar":{"title":"Adhkar apr\xe8s la pri\xe8re","description":"Ayat al-Kursi et les trois Qul apr\xe8s chaque pri\xe8re, en arabe avec traduction anglaise ou ourdoue. D\xe9sactiv\xe9 jusqu\u2019\xe0 ce que vous l\u2019activiez."},"hifz":{"title":"Hifz Coach","description":"M\xe9morisez quelques versets \xe0 la fois sur votre Echo : chaque verset trois fois, puis toute la le\xe7on, avec votre progression enregistr\xe9e. Entra\xeenez-vous aussi en ligne."},"ramadan":{"title":"Mode Ramadan","description":"Un rappel du Suhour avant Fajr, l\u2019Iftar annonc\xe9 \xe0 Maghrib et la r\xe9citation des Tarawih de La Mecque apr\xe8s Isha."},"show":{"title":"\xc9cran Echo Show","description":"Les horaires du jour \xe0 l\u2019\xe9cran, la prochaine pri\xe8re mise en avant avec un compte \xe0 rebours, et un widget Horaires de pri\xe8re toujours visible."},"scenes":{"title":"Sc\xe8nes de la maison","description":"Tamisez les lumi\xe8res \xe0 l\u2019Athan, r\xe9veillez-vous en douceur avant Fajr ou cr\xe9ez une soir\xe9e calme apr\xe8s Isha, avec vos routines Alexa."},"duas":{"title":"Douas apr\xe8s l\u2019Athan","description":"La doua apr\xe8s l\u2019Athan et les douas de votre choix, sur votre Echo juste apr\xe8s l\u2019Athan."},"qibla":{"title":"Direction de la Qibla","description":"Demandez o\xf9 est la Qibla : la direction depuis chez vous en degr\xe9s et en point cardinal, et la distance jusqu\u2019\xe0 La Mecque."},"hijri":{"title":"Date h\xe9girienne et calendrier islamique","description":"La date h\xe9girienne du jour, et combien de jours avant Ramadan, l\u2019A\xefd, Achoura, Arafat ou les jours blancs. Les m\xeames dates que vos horaires de pri\xe8re."},"fasting":{"title":"Je\xfbnes sur\xe9rogatoires","description":"Demandez quand est le prochain je\xfbne de la Sunna, ou recevez un rappel apr\xe8s Isha la veille des lundis, jeudis, jours blancs, Arafat et Achoura."},"tasbih":{"title":"Tasbih et adhkar du matin et du soir","description":"Alexa compte le dhikr avec vous (33, 33, 34 apr\xe8s la pri\xe8re), avec un compteur tactile sur Echo Show, et diffuse les adhkar du matin et du soir."},"translation":{"title":"Coran avec traduction","description":"\xc9coutez n\u2019importe quelle sourate \xe0 la voix, avec l\u2019anglais ou l\u2019ourdou apr\xe8s chaque verset, et la sourate Al-Kahf chaque vendredi."},"daily":{"title":"Doua, hadith et Noms d\u2019Allah du jour","description":"Une courte doua, un hadith ou l\u2019un des 99 Noms chaque jour, avec sa source, relu par un savant avant publication."}}},"screens":{"h2":"Voyez-le en action","sub":"De vrais \xe9crans d\u2019une famille qui suit l\u2019AMCC en Floride : les horaires de pri\xe8re pour leur position, les heures d\u2019iqama publi\xe9es par la mosqu\xe9e.","showAlt":"\xc9cran Echo Show : horaires du jour avec les iqamas de la mosqu\xe9e, la prochaine pri\xe8re, Maghrib, mise en avant avec un compte \xe0 rebours","showH":"Sur votre Echo Show","showP":"Dites \xab <q>{{p1}}</q> \xbb (demande \xe0 Muslim Companion les horaires du jour) : les cinq pri\xe8res et le lever du soleil, l\u2019iqama de votre mosqu\xe9e \xe0 c\xf4t\xe9 de chacune, et la prochaine pri\xe8re mise en avant avec un compte \xe0 rebours.","phoneAlt":"Ma mosqu\xe9e sur un t\xe9l\xe9phone : la mosqu\xe9e, les heures d\u2019athan et d\u2019iqama du jour, la Joumou\u2019a et les choix de rappels Echo","phoneH":"Sur votre t\xe9l\xe9phone","phoneP":"Sur <a>alexa.imuslimlife.com</a>, ouvrez <b>Ma mosqu\xe9e</b> et choisissez votre mosqu\xe9e. Vous voyez les heures d\u2019athan et d\u2019iqama du jour et la Joumou\u2019a de ce vendredi, et vous choisissez quand votre Echo vous pr\xe9vient avant l\u2019iqama et la Joumou\u2019a.","widgetAlt":"Widget Horaires de pri\xe8re : prochaine pri\xe8re Maghrib avec compte \xe0 rebours, heure d\u2019iqama et les cinq pri\xe8res du jour","widgetH":"Widget toujours visible","widgetP":"Sur Echo Show 8, 10 et 15, ajoutez le widget <b>Horaires de pri\xe8re</b> : la prochaine pri\xe8re, son compte \xe0 rebours et l\u2019iqama de votre mosqu\xe9e restent sur l\u2019\xe9cran d\u2019accueil."},"voice":{"h2":"Commandes vocales","sub":"Tout ce que vous pouvez dire \xe0 Muslim Companion, class\xe9 par fonctionnalit\xe9. Vous utilisez un assistant IA ? <a>Connectez-le \xe0 nos horaires de pri\xe8re</a>."},"ref":{"langsTitle":"Langues et pays","langsBody":"Muslim Companion comprend l\u2019<b>anglais</b>, l\u2019<b>arabe</b> (\xab \u0627\u0644\u0631\u0641\u064a\u0642 \u0627\u0644\u0645\u0633\u0644\u0645 \xbb) et l\u2019<b>hindi</b> (\xab \u092e\u0941\u0938\u094d\u0932\u093f\u092e \u0915\u092e\u094d\u092a\u0948\u0928\u093f\u092f\u0928 \xbb). En anglais, dites les phrases exactement comme \xe9crites, en commen\xe7ant par \xab <q>{{p1}}</q> \xbb (le nom est le m\xeame aux <b>\xc9tats-Unis, au Canada, au Royaume-Uni, en Inde et en Australie</b>). Choisissez une langue ci-dessus pour voir les phrases en arabe ou en hindi. Quand une phrase offre un choix, comme une m\xe9thode de calcul, la description liste toutes les options.","soonNote":"Les commandes marqu\xe9es <b>Bient\xf4t</b> ne sont pas encore disponibles ; le badge indique pourquoi.","english":"English","soonSuffix":" \xb7 bient\xf4t","langNote":"<b>{{title}}</b> : r\xe9glez la langue d\u2019Alexa sur {{lang}} pour utiliser Muslim Companion dans cette langue. Le nom du skill dans cette langue est <n>{{name}}</n>. Voici les phrases exactes qu\u2019il comprend ; les descriptions restent en anglais.","langAr":"arabe (Arabie saoudite)","langHi":"hindi (Inde)","all":"Tout","comingSoon":"Bient\xf4t","showsOnShow":"S\u2019affiche sur Echo Show","whilePlaying":"Pendant la lecture de Muslim Companion","turnsOff":"D\xe9sactive l\u2019Athan automatique","tip":"Astuce : {{tip}}","footer":"Vous pouvez aussi commencer par \xab <q>{{p1}}</q> \xbb (Alexa, ouvre Muslim Companion) puis demander. Les commandes \xab <q>next</q> \xbb (suivant), \xab <q>pause</q> \xbb et \xab <q>stop</q> \xbb fonctionnent pendant la lecture."},"api":{"h2":"Propuls\xe9 par notre API \xe9prouv\xe9e","p":"Le skill Alexa Muslim Companion repose sur notre API d\u2019horaires de pri\xe8re fiable, qui calcule pr\xe9cis\xe9ment selon votre position exacte.","methods":{"primary":"23 m\xe9thodes de calcul + Asr hanafite ou standard","secondary":"ISNA, Ligue islamique mondiale, Umm al-Qura, \xc9gypte, Karachi, Golfe, Kowe\xeft, Qatar, Singapour, France, Turquie, Russie, T\xe9h\xe9ran et Jafari, au tableau de bord ou \xe0 la voix"},"hijri":{"primary":"Calendrier h\xe9girien int\xe9gr\xe9","secondary":"Des dates islamiques exactes avec les horaires de pri\xe8re"},"perf":{"primary":"Hautes performances","secondary":"Optimis\xe9e pour la vitesse et la fiabilit\xe9"},"free":{"primary":"Gratuite pour la communaut\xe9","secondary":"L\u2019API des horaires de pri\xe8re est gratuite"},"cta":"D\xe9couvrir notre API","imgAlt":"Illustration de l\u2019API"},"cta":{"h2":"Pr\xeat \xe0 entendre l\u2019Athan sur Alexa ?","p":"Le skill est disponible. Configurez votre programme de pri\xe8re personnalis\xe9 en moins de cinq minutes.","guide":"Voir le guide d\u2019installation","small":"Gratuit pour toujours \xb7 Aucune app \xe0 t\xe9l\xe9charger \xb7 Compatible avec tous les Echo"},"faq":{"h2":"Questions fr\xe9quentes","devices":{"q":"Avec quels appareils Alexa ce skill fonctionne-t-il ?","a":"Le skill Muslim Companion fonctionne avec tout appareil Amazon Echo ou compatible Alexa. Pour le meilleur son, nous recommandons des appareils dot\xe9s de bons haut-parleurs comme l\u2019Echo, l\u2019Echo Dot ou l\u2019Echo Show."},"dst":{"q":"Le skill s\u2019adapte-t-il automatiquement \xe0 l\u2019heure d\u2019\xe9t\xe9 ?","a":"Oui, le skill ajuste automatiquement les horaires selon le fuseau horaire de votre position et les changements d\u2019heure. Vos horaires restent exacts sans aucun r\xe9glage manuel."},"choose":{"q":"Puis-je choisir les pri\xe8res qui diffusent l\u2019athan ?","a":"Bien s\xfbr ! Vous choisissez les pri\xe8res qui diffusent l\u2019athan : par exemple seulement Fajr, Maghrib et Isha, ou les cinq pri\xe8res. Cela se r\xe8gle sur la page Param\xe8tres de pri\xe8re d\u2019alexa.imuslimlife.com."},"cost":{"q":"Ce skill est-il payant ?","a":"Le skill Muslim Companion est enti\xe8rement gratuit. L\u2019essentiel, des horaires exacts et l\u2019athan automatique, reste gratuit pour la communaut\xe9 musulmane, pour toujours."},"offline":{"q":"Et si ma connexion Internet est coup\xe9e ?","a":"Vos horaires sont calcul\xe9s \xe0 l\u2019avance, mais votre Echo a besoin d\u2019Internet pour diffuser l\u2019Athan. Si la connexion est coup\xe9e \xe0 l\u2019heure de la pri\xe8re, cet Athan peut \xeatre manqu\xe9 ; tout reprend automatiquement au retour de la connexion."}}}')}}]);